+
+    @Override
+    public void add(double x, int w) {
+        checkValue(x);
+        for (int i = 0; i < w; i++) {
+            values.add(x);
+        }
+        isSorted = false;
+        max = Math.max(max, x);
+        min = Math.min(min, x);
+    }
+
+    @Override
+    public void add(List<? extends TDigest> others) {
+        long valuesToAddCount = 0;
+        for (TDigest other : others) {
+            valuesToAddCount += other.size();
+        }
+        reserve(valuesToAddCount);
+
+        for (TDigest other : others) {
+            for (Centroid centroid : other.centroids()) {
+                add(centroid.mean(), centroid.count());
+            }
+        }
+    }
+
+    @Override
+    public void compress() {
+        if (isSorted == false) {
+            Collections.sort(values);
+            isSorted = true;
+        }
+    }
+
+    @Override
+    public long size() {
+        return values.size();
+    }
+
+    @Override
+    public double cdf(double x) {
+        compress();
+        return Dist.cdf(x, values);
+    }
+
+    @Override
+    public double quantile(double q) {
+        compress();
+        return Dist.quantile(q, values);
+    }
+
+    @Override
+    public Collection<Centroid> centroids() {
+        compress();
+
+        return new AbstractCollection<>() {
+            @Override
+            public Iterator<Centroid> iterator() {
+                return new Iterator<>() {
+                    int i = 0;
+
+                    @Override
+                    public boolean hasNext() {
+                        return i < values.size();
+                    }
+
+                    @Override
+                    public Centroid next() {
+                        Centroid rc = new Centroid(values.get(i), 1);
+                        i++;
+                        return rc;
+                    }
+
+                    @Override
+                    public void remove() {
+                        throw new UnsupportedOperationException("Default operation");
+                    }
+                };
+            }
+
+            @Override
+            public int size() {
+                return values.size();
+            }
+        };
+    }
+
+    @Override
+    public double compression() {
+        return 1;
+    }
+
+    @Override
+    public int centroidCount() {
+        return centroids().size();
+    }
+
+    @Override
+    public void reserve(long size) {
+        int newSize = (size + values.size() > Integer.MAX_VALUE) ? Integer.MAX_VALUE : values.size() + (int) size;
+        values.ensureCapacity(newSize);
+    }
+
+    /**
+     * Returns an upper bound on the number bytes that will be required to represent this histogram.
+     */
+    @Override
+    public int byteSize() {
